"""Minimal YAML renderer (stdlib only)."""

from plugins import PluginError, Renderer, register


def _yaml_value(v):
    """Return a YAML-safe string representation of a scalar value."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    # string
    s = str(v)
    # Quote if the value could be misinterpreted
    if s == "" or s in ("true", "false", "null", "yes", "no", "on", "off"):
        return "'" + s.replace("'", "''") + "'"
    if any(c in s for c in ":{}[]&*?|->!%@#,"):
        return "'" + s.replace("'", "''") + "'"
    return s


def _yaml_row(row, indent):
    """Render a single dict as YAML lines."""
    prefix = "  " * indent
    lines = []
    for k, v in row.items():
        if isinstance(v, dict):
            lines.append(f"{prefix}{k}:")
            for dk, dv in v.items():
                lines.append(f"{prefix}  {dk}: {_yaml_value(dv)}")
        else:
            lines.append(f"{prefix}{k}: {_yaml_value(v)}")
    return lines


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for row in rows:
            lines.append("-")
            lines.extend(_yaml_row(row, indent=1))
        return "\n".join(lines) + "\n"

