"""YAML renderer plugin.

Uses only the standard library so it stays within the CONTRIBUTING.md constraint.
"""

from plugins import PluginError, Renderer, register


def _to_yaml(obj, indent=0) -> str:
    """Minimal YAML serializer for flat dicts and their scalar values."""
    lines: list[str] = []
    prefix = "  " * indent
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, dict):
                lines.append(f"{prefix}{k}:")
                lines.append(_to_yaml(v, indent + 1))
            elif isinstance(v, list):
                lines.append(f"{prefix}{k}:")
                for item in v:
                    if isinstance(item, dict):
                        # block sequence of mappings
                        lines.append(f"{prefix}-")
                        lines.append(_to_yaml(item, indent + 2))
                    else:
                        lines.append(f"{prefix}- {_format_scalar(item)}")
            else:
                lines.append(f"{prefix}{k}: {_format_scalar(v)}")
    return "\n".join(lines)


def _format_scalar(v) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if v is None:
        return "null"
    if isinstance(v, str):
        # Quote strings that could be misinterpreted
        if v == "" or v in ("true", "false", "null", "yes", "no",
                             "on", "off", "True", "False", "Null",
                             "Yes", "No", "On", "Off"):
            return f"'{v}'"
        if any(c in v for c in ":{}[]&*?|->!%@#,`"):
            return f"'{v}'"
        return v
    return str(v)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        # Render each row as a block sequence item
        lines = []
        for row in rows:
            lines.append(_to_yaml(row))
