"""Minimal YAML renderer (standard library only)."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Return a YAML-safe scalar string for *value*."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return _format_float(value)
    if isinstance(value, str):
        return _quote_str(value)
    # Fallback: str()
    return _quote_str(str(value))


def _format_float(v: float) -> str:
    """Format a float without unnecessary trailing zeros, but keep at least one
    decimal digit so the result is unambiguously a float."""
    s = f"{v:.10f}".rstrip("0")
    if s.endswith("."):
        s += "0"
    return s


def _quote_str(s: str) -> str:
    """Return *s* as a YAML scalar, double-quoted when necessary."""
    # Strings that are empty, look like booleans/null, start/end with
    # special chars, contain :, #, {, }, [, ], ,, &, *, ?, |, -, <, >, =, !,
    # %, @, `, or contain newlines / leading/trailing whitespace must be quoted.
    needs_quote = (
        s == ""
        or s in ("true", "false", "yes", "no", "on", "off", "null", "~")
        or s in ("true", "false", "True", "False", "TRUE", "FALSE")
        or s in ("y", "Y", "n", "N")
        or s in ("null", "Null", "NULL")
        or s[0] in (" ", "\t")
        or s[-1] in (" ", "\t")
        or ":" in s
        or "# " in s
        or s.startswith(("{", "}", "[", "]", ",", "&", "*", "?", "|", "-", "<", ">", "=", "!", "%", "@", "`"))
        or "\n" in s
        or "\r" in s
    )
    if needs_quote:
        escaped = s.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'
    return s


def _yaml_block(rows: list[dict]) -> str:
    """Render a list of flat dicts as a YAML block sequence."""
    if not rows:
        return "[]"
    lines: list[str] = []
    for row in rows:
        if not row:
            lines.append("- {}")
            continue
        lines.append("-")
        for key, value in row.items():
            lines.append(f"  {key}: {_yaml_scalar(value)}")
    return "\n".join(lines)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_block(rows) + "\n"

